        {"teks": "250.000.000 lembar", "andaian": true}
      ],
      "kartu": ["fil-2025-08-25-03", "fil-2025-08-25-04", "fil-2025-09-01-01", "jumlah-jual-terverifikasi"],
      "kartu_penentu": ["jumlah-jual-terverifikasi"],
      "pilihan": {
        "a": "Betul, [[fil-2025-08-25-03|70.000.000 lembar]] itu total seluruh penjualannya.",
        "b": "Keliru, totalnya [[jumlah-jual-terverifikasi|299.500.000 lembar]].",
        "c": "Betul, angkanya cocok dengan [[fil-2025-08-25-04|179.500.000 lembar]].",
        "d": "Keliru, pemilik terbesar tidak pernah melaporkan penjualan saham."
      },
      "kunci": "b",
      "penjelasan": "Tiga laporan kepemilikan yang diumumkan ke publik mencatat penjualan pemilik terbesar: [[fil-2025-08-25-03|70.000.000 lembar]], [[fil-2025-08-25-04|179.500.000 lembar]], dan [[fil-2025-09-01-01|50.000.000 lembar]]. Kartu hitungan [[jumlah-jual-terverifikasi|299.500.000 lembar]] menjumlahkan ketiganya, jadi angka di pesan tidak cocok dengan dokumen. Salah-kaprah yang umum: percaya angka bulat yang disebut di grup tanpa mengecek satu per satu laporan yang sudah diumumkan ke publik."
    }
  ]
}

